import{_ as e,o as r,c as t,a2 as o}from"./chunks/framework.EUByU7Iq.js";const u=JSON.parse('{"title":"第二章 公司登记","description":"","frontmatter":{"title":"第二章 公司登记","date":"2023-12-29T00:00:00.000Z","categories":["法律","公司法"],"tags":["法律","公司法"],"law_version":"2023修订（2023-12-29 公布，2024-07-01 施行）","v1_source":"blogs/CL/第二章：公司登记.md"},"headers":[],"relativePath":"blogs/CL/dierzhang：gongsidengji.md","filePath":"blogs/CL/第二章：公司登记.md"}'),i={name:"blogs/CL/dierzhang：gongsidengji.md"};function h(l,a,n,d,s,c){return r(),t("div",null,[...a[0]||(a[0]=[o('<h1 id="第二章-公司登记" tabindex="-1">第二章 公司登记 <a class="header-anchor" href="#第二章-公司登记" aria-label="Permalink to &quot;第二章 公司登记&quot;">​</a></h1><h3 id="第二十九条" tabindex="-1">第二十九条 <a class="header-anchor" href="#第二十九条" aria-label="Permalink to &quot;第二十九条&quot;">​</a></h3><p>九条设立公司，应当依法向公司登记机关申请设立登记。 法律、行政法规规定设立公司必须报经批准的，应当在公司登记前依法办理批准手续。</p><h3 id="第三十条" tabindex="-1">第三十条 <a class="header-anchor" href="#第三十条" aria-label="Permalink to &quot;第三十条&quot;">​</a></h3><p>十条申请设立公司，应当提交设立登记申请书、公司章程等文件，提交的相关材料应当真实、合法和有效。 申请材料不齐全或者不符合法定形式的，公司登记机关应当一次性告知需要补正的材料。</p><h3 id="第三十一条" tabindex="-1">第三十一条 <a class="header-anchor" href="#第三十一条" aria-label="Permalink to &quot;第三十一条&quot;">​</a></h3><p>一条申请设立公司，符合本法规定的设立条件的，由公司登记机关分别登记为有限责任公司或者股份有限公司；不符合本法规定的设立条件的，不得登记为有限责任公司或者股份有限公司。</p><h3 id="第三十二条" tabindex="-1">第三十二条 <a class="header-anchor" href="#第三十二条" aria-label="Permalink to &quot;第三十二条&quot;">​</a></h3><p>二条公司登记事项包括： （一）名称； （二）住所； （三）注册资本； （四）经营范围； （五）法定代表人的姓名； （六）有限责任公司股东、股份有限公司发起人的姓名或者名称。 公司登记机关应当将前款规定的公司登记事项通过国家企业信用信息公示系统向社会公示。</p><h3 id="第三十三条" tabindex="-1">第三十三条 <a class="header-anchor" href="#第三十三条" aria-label="Permalink to &quot;第三十三条&quot;">​</a></h3><p>三条依法设立的公司，由公司登记机关发给公司营业执照。公司营业执照签发日期为公司成立日期。 公司营业执照应当载明公司的名称、住所、注册资本、经营范围、法定代表人姓名等事项。 公司登记机关可以发给电子营业执照。电子营业执照与纸质营业执照具有同等法律效力。</p><h3 id="第三十四条" tabindex="-1">第三十四条 <a class="header-anchor" href="#第三十四条" aria-label="Permalink to &quot;第三十四条&quot;">​</a></h3><p>四条公司登记事项发生变更的，应当依法办理变更登记。 公司登记事项未经登记或者未经变更登记，不得对抗善意相对人。</p><h3 id="第三十五条" tabindex="-1">第三十五条 <a class="header-anchor" href="#第三十五条" aria-label="Permalink to &quot;第三十五条&quot;">​</a></h3><p>五条公司申请变更登记，应当向公司登记机关提交公司法定代表人签署的变更登记申请书、依法作出的变更决议或者决定等文件。 公司变更登记事项涉及修改公司章程的，应当提交修改后的公司章程。 公司变更法定代表人的，变更登记申请书由变更后的法定代表人签署。</p><h3 id="第三十六条" tabindex="-1">第三十六条 <a class="header-anchor" href="#第三十六条" aria-label="Permalink to &quot;第三十六条&quot;">​</a></h3><p>六条公司营业执照记载的事项发生变更的，公司办理变更登记后，由公司登记机关换发营业执照。</p><h3 id="第三十七条" tabindex="-1">第三十七条 <a class="header-anchor" href="#第三十七条" aria-label="Permalink to &quot;第三十七条&quot;">​</a></h3><p>七条公司因解散、被宣告破产或者其他法定事由需要终止的，应当依法向公司登记机关申请注销登记，由公司登记机关公告公司终止。</p><h3 id="第三十八条" tabindex="-1">第三十八条 <a class="header-anchor" href="#第三十八条" aria-label="Permalink to &quot;第三十八条&quot;">​</a></h3><p>八条公司设立分公司，应当向公司登记机关申请登记，领取营业执照。</p><h3 id="第三十九条" tabindex="-1">第三十九条 <a class="header-anchor" href="#第三十九条" aria-label="Permalink to &quot;第三十九条&quot;">​</a></h3><p>九条虚报注册资本、提交虚假材料或者采取其他欺诈手段隐瞒重要事实取得公司设立登记的，公司登记机关应当依照法律、行政法规的规定予以撤销。</p><h3 id="第四十条" tabindex="-1">第四十条 <a class="header-anchor" href="#第四十条" aria-label="Permalink to &quot;第四十条&quot;">​</a></h3><p>十条公司应当按照规定通过国家企业信用信息公示系统公示下列事项： （一）有限责任公司股东认缴和实缴的出资额、出资方式和出资日期，股份有限公司发起人认购的股份数； （二）有限责任公司股东、股份有限公司发起人的股权、股份变更信息； （三）行政许可取得、变更、注销等信息； （四）法律、行政法规规定的其他信息。 公司应当确保前款公示信息真实、准确、完整。</p><h3 id="第四十一条" tabindex="-1">第四十一条 <a class="header-anchor" href="#第四十一条" aria-label="Permalink to &quot;第四十一条&quot;">​</a></h3><p>一条公司登记机关应当优化公司登记办理流程，提高公司登记效率，加强信息化建设，推行网上办理等便捷方式，提升公司登记便利化水平。 国务院市场监督管理部门根据本法和有关法律、行政法规的规定，制定公司登记注册的具体办法。</p><hr><p class="law-foot">本篇依据《中华人民共和国公司法》2023 年 12 月 29 日第十四届全国人大常委会第七次会议第二次修订文本，自 2024 年 7 月 1 日起施行；本站同步于 2026-11-07。</p>',29)])])}const b=e(i,[["render",h]]);export{u as __pageData,b as default};
